/**
 * Every Organization the caller belongs to, with the caller's role and that
 * Organization's active Projects, in one read. Workspace entry uses this to
 * resolve its destination without a request per Organization: no
 * Organizations means create one, an Organization without Projects means
 * create a Project, otherwise land in a Project. Projects are capped per
 * Organization; projectsTruncated reports when the list is partial and
 * projectCount carries the true total.
 *
 */
export const getWorkspaceBootstrap = <ThrowOnError extends boolean = false>(options?: Options<GetWorkspaceBootstrapData, ThrowOnError>): RequestResult<GetWorkspaceBootstrapResponses, GetWorkspaceBootstrapErrors, ThrowOnError> => (options?.client ?? client).get<GetWorkspaceBootstrapResponses, GetWorkspaceBootstrapErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'mosaic_session',
            type: 'apiKey'
        }],
    url: '/v1/workspace/bootstrap',
    ...options
});
